import React from 'react';
import { Box, Typography, IconButton, Stack, Paper } from '@mui/material';
import {
  Savings,
  AccountBalanceWallet,
  Payment,
  History,
  AddCircleOutline,
  MoreHoriz,
} from '@mui/icons-material';

const menuItems = [
  { label: 'เงินดาวน์', icon: <Savings /> },
  { label: 'สินเชื่อ', icon: <AccountBalanceWallet /> },
  { label: 'ชำระเงิน', icon: <Payment /> },
  { label: 'ประวัติ', icon: <History /> },
  { label: 'สินเชื่อใหม่', icon: <AddCircleOutline /> },
  { label: 'เมนูอื่น ๆ', icon: <MoreHoriz /> },
];

const HomeMenu = () => {
  return (
    <Box p={3} bgcolor="background.default">
      <Stack direction="row" flexWrap="wrap" spacing={2} useFlexGap justifyItems={'center'} justifyContent={'center'}>
        {menuItems.map((item, index) => (
          <Paper
            key={index}
            elevation={1}
            sx={{
              width: '120px',
              height: '120px',
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'center',
              justifyContent: 'center',
              background: 'linear-gradient(135deg, #2f9275ff 0%, #2c967bff 50%, #0e8d78ff 100%)',
              '&:hover': {
                background: 'linear-gradient(135deg, #266955ff 0%, #125f4cff 50%, #0e8d78ff 100%)',
                cursor: 'pointer',
              },
            }}
          >
            <IconButton color='info'>{item.icon}</IconButton>
            <Typography variant="body2" mt={1} color='info'>
              {item.label}
            </Typography>
          </Paper>
        ))}
      </Stack>
    </Box>
  );
};

export default HomeMenu;
